#!/usr/bin/env python3
"""Generate realistic synthetic labelled resumes for all 25 Kaggle resume categories.

Each resume is hand-crafted to closely mirror real-world resume language —
varied section order, mixed skill lists, first/third person, quantified achievements.
No network calls required.

Usage:
    python scripts/seed_resumes.py                      # 20 per category → 500 records
    python scripts/seed_resumes.py --per-category 30   # 750 records
    python scripts/seed_resumes.py --append             # add to existing file
"""
from __future__ import annotations

import argparse
import random
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
from src.config import RAW_DATA_DIR, ensure_project_directories  # noqa: E402

