def _make_record(category: str, text: str) -> str:
    return f"CATEGORY: {category}\nRESUME:\n{text}\n---"


def generate_seed_records(per_category: int, seed: int = 42) -> list[str]:
    rng = random.Random(seed)
    records: list[str] = []
    suffix_options = [
        " Strong communication and collaboration skills across cross-functional teams.",
        " Delivered results under tight deadlines with high attention to quality.",
        " Committed to continuous learning and professional development.",
        " Track record of mentoring junior team members and knowledge sharing.",
        " Experienced working in fast-paced Agile and Scrum environments.",
        " Proven ability to manage multiple priorities and stakeholder expectations.",
        " Strong analytical and problem-solving skills with a data-driven mindset.",
        " Proactive in identifying process improvements and implementing solutions.",
    ]
    for category, templates in _TEMPLATES.items():
        pool = list(templates)
        chosen: list[str] = []
        while len(chosen) < per_category:
            batch = pool[:]
            rng.shuffle(batch)
            chosen.extend(batch)
        for i, text in enumerate(chosen[:per_category]):
            if i >= len(templates):
                text = text.rstrip(".") + "." + rng.choice(suffix_options)
            records.append(_make_record(category, text))
    return records


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--per-category", type=int, default=20,
                        help="Resumes per category (default: 20; 25 categories → 500 total).")
    parser.add_argument("--output", type=Path, default=RAW_DATA_DIR / "resumes.txt")
    parser.add_argument("--append", action="store_true",
                        help="Append to existing file instead of overwriting.")
    parser.add_argument("--seed", type=int, default=42, help="Random seed (default: 42).")
    args = parser.parse_args()
    if args.per_category < 2:
        parser.error("--per-category must be at least 2.")
    ensure_project_directories()
    records = generate_seed_records(args.per_category, seed=args.seed)
    mode = "a" if args.append else "w"
    with args.output.open(mode, encoding="utf-8") as fh:
        if args.append and args.output.exists() and args.output.stat().st_size:
            fh.write("\n\n")
        fh.write("\n\n".join(records).rstrip() + "\n")
    total = len(_TEMPLATES) * args.per_category
    print(f"Wrote {total} synthetic seed resumes across {len(_TEMPLATES)} categories to {args.output}")


if __name__ == "__main__":
    main()
